const roles={teacher:['Help a community grow.','Help other players learn, find your place in a school and become part of the community’s next chapter.'],trader:['Make a living. Make a name.','Start a business, trade with other players and build the kind of reputation that brings people back.'],neighbour:['Find your own people.','Build friendships, form a household and turn a place on the map into somewhere you belong.'],leader:['Take responsibility.','Serve your community, make difficult decisions and experience how public choices affect everyday lives.']};
document.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const role=roles[button.dataset.role];document.getElementById('role-title').textContent=role[0];document.getElementById('role-description').textContent=role[1];}));
const privacy=document.getElementById('privacy-dialog');document.getElementById('privacy-open').addEventListener('click',()=>privacy.showModal());privacy.addEventListener('click',event=>{if(event.target===privacy){const r=privacy.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)privacy.close();}});
